func TestNovelReportBehavior(t *testing.T) {
	rep := topicReport{
		Topic: "long covid", Total: 120, Recruiting: 30, RecruitingPct: 25, SampleSize: 100,
		Phases:    []rankedEntry{{Label: "Phase 2", Count: 40}},
		Countries: []rankedEntry{{Label: "United States", Count: 60}},
		Sponsors:  []rankedEntry{{Label: "NIH", Count: 12}},
	}

	t.Run("markdown", func(t *testing.T) {
		cmd := &cobra.Command{}
		var buf bytes.Buffer
		cmd.SetOut(&buf)
		if err := renderReportMarkdown(cmd, rep); err != nil {
			t.Fatalf("renderReportMarkdown: %v", err)
		}
		out := buf.String()
		for _, want := range []string{"# Clinical Trials Briefing: long covid", "**Total trials:** 120", "## Phase distribution", "| United States | 60 |"} {
			if !strings.Contains(out, want) {
				t.Errorf("markdown output missing %q\n---\n%s", want, out)
			}
		}
	})

	t.Run("csv", func(t *testing.T) {
		cmd := &cobra.Command{}
		var buf bytes.Buffer
		cmd.SetOut(&buf)
		if err := renderReportCSV(cmd, rep); err != nil {
			t.Fatalf("renderReportCSV: %v", err)
		}
		out := buf.String()
		for _, want := range []string{"section,label,count", "summary,total_trials,120", "phase,Phase 2,40", "sponsor,NIH,12"} {
			if !strings.Contains(out, want) {
				t.Errorf("csv output missing %q\n---\n%s", want, out)
			}
		}
	})
}
